Json::Value Configuration::toJson() const
{
    Json::Value ret;
    if(getId())
    {
        ret["id"]=getValueOfId();
    }
    else
    {
        ret["id"]=Json::Value();
    }
    if(getName())
    {
        ret["name"]=getValueOfName();
    }
    else
    {
        ret["name"]=Json::Value();
    }
    if(getValue())
    {
        ret["value"]=getValueOfValue();
    }
    else
    {
        ret["value"]=Json::Value();
    }
    if(getDateValue())
    {
        ret["date_value"]=getDateValue()->toDbStringLocal();
    }
    else
    {
        ret["date_value"]=Json::Value();
    }
    if(getIsEnabled())
    {
        ret["is_enabled"]=getValueOfIsEnabled();
    }
    else
    {
        ret["is_enabled"]=Json::Value();
    }
    if(getDescription())
    {
        ret["description"]=getValueOfDescription();
    }
    else
    {
        ret["description"]=Json::Value();
    }
    if(getModifiedAt())
    {
        ret["modified_at"]=getModifiedAt()->toDbStringLocal();
    }
    else
    {
        ret["modified_at"]=Json::Value();
    }
    return ret;
}

std::string Configuration::toString() const
{
    return toJson().toStyledString();
}

